initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Create Entity From File with Response Status Code set to 400     and
        Create Entity From File with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/InvalidRequest'     and
        Create Entity From File with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entities/'
        method set to 'POST'
        Request creation of an entity from filename 'invalid-json-sample.jsonld' and Content-Type set to 'application/ld+json'
}

